#!/usr/bin/env node

import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  statSync,
  writeFileSync,
} from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import prettier from 'prettier';

import { renderMarkdownWithToc } from './generate-markdown-tocs.mjs';

const GENERATED_NOTICE =
  '<!-- Generated by scripts/generate-docs-index.mjs; edit source docs or generator, then run `pnpm docs:index:write`. -->';

const ACTIVE_CATALOG_ROOTS = [
  'architecture',
  'decisions',
  'engineering',
  'operations',
  'planning',
  'product',
  'generated',
];

const GENERATED_INDEX_FILES = new Set([
  'docs/README.md',
  'docs/decisions/README.md',
  'docs/archive/README.md',
]);

function normalizePath(filePath) {
  return filePath.split(path.sep).join('/');
}

function todayIsoDate() {
  return new Date().toISOString().slice(0, 10);
}

function readText(filePath) {
  return readFileSync(filePath, 'utf8');
}

function escapeCell(value) {
  return String(value ?? '-')
    .replaceAll(/\r?\n/g, ' ')
    .replaceAll('|', String.raw`\|`)
    .trim();
}

function renderTable(headers, rows) {
  return [
    `| ${headers.map(escapeCell).join(' | ')} |`,
    `| ${headers.map(() => '---').join(' | ')} |`,
    ...rows.map((row) => `| ${row.map(escapeCell).join(' | ')} |`),
  ].join('\n');
}

function parseFrontmatter(content) {
  if (!content.startsWith('---\n')) {
    return {};
  }

  const end = content.indexOf('\n---', 4);

  if (end === -1) {
    return {};
  }

  const metadata = {};
  const body = content.slice(4, end);

  for (const line of body.split(/\r?\n/)) {
    const separatorIndex = line.indexOf(':');

    if (separatorIndex <= 0) {
      continue;
    }

    const key = line.slice(0, separatorIndex);

    if (!/^[\w-]+$/u.test(key)) {
      continue;
    }

    metadata[key] = line
      .slice(separatorIndex + 1)
      .trim()
      .replace(/^['"]|['"]$/g, '');
  }

  return metadata;
}

function extractHeading(content) {
  for (const line of content.split(/\r?\n/)) {
    const normalizedLine = line.trimEnd();

    if (normalizedLine.startsWith('# ')) {
      return normalizedLine.slice(2).trim();
    }
  }

  return 'Sans titre';
}

function stripHtmlTags(value) {
  let result = '';
  let pendingTag = '';
  let insideTag = false;

  for (const character of value) {
    if (character === '<') {
      insideTag = true;
      pendingTag = character;
      continue;
    }

    if (!insideTag) {
      result += character;
      continue;
    }

    pendingTag += character;

    if (character === '>') {
      insideTag = false;
      pendingTag = '';
    }
  }

  return insideTag ? result + pendingTag : result;
}

function stripMarkdown(value) {
  return stripHtmlTags(value).replaceAll('**', '').replaceAll('`', '').trim();
}

function readMarkdownRecord(root, relativeFile) {
  const absoluteFile = path.join(root, relativeFile);
  const content = readText(absoluteFile);
  const metadata = parseFrontmatter(content);

  return {
    content,
    metadata,
    relativeFile: normalizePath(relativeFile),
    title: extractHeading(content),
  };
}

function walkMarkdown(root, directory) {
  const absoluteDirectory = path.join(root, directory);

  if (!existsSync(absoluteDirectory)) {
    return [];
  }

  const files = [];

  function walk(currentDirectory) {
    for (const entry of readdirSync(currentDirectory, {
      withFileTypes: true,
    })) {
      const absoluteEntry = path.join(currentDirectory, entry.name);

      if (entry.isDirectory()) {
        walk(absoluteEntry);
        continue;
      }

      if (entry.isFile() && entry.name.toLowerCase().endsWith('.md')) {
        files.push(normalizePath(path.relative(root, absoluteEntry)));
      }
    }
  }

  walk(absoluteDirectory);

  return files.sort((left, right) => left.localeCompare(right, 'fr'));
}

function preservedFrontmatter(root, targetFile, today) {
  const absoluteFile = path.join(root, targetFile);
  const existing = existsSync(absoluteFile)
    ? parseFrontmatter(readText(absoluteFile))
    : {};

  return [
    '---',
    `status: ${existing.status ?? 'active'}`,
    `owner: ${existing.owner ?? 'platform'}`,
    `last_reviewed: ${existing.last_reviewed ?? today}`,
    `source_of_truth: ${existing.source_of_truth ?? 'true'}`,
    '---',
    '',
    '',
  ].join('\n');
}

function activeDocuments(root) {
  const files = ACTIVE_CATALOG_ROOTS.flatMap((directory) =>
    walkMarkdown(root, path.join('docs', directory)),
  );

  return files
    .filter((file) => !GENERATED_INDEX_FILES.has(file))
    .map((file) => readMarkdownRecord(root, file))
    .filter((record) => record.metadata.status === 'active')
    .map((record) => ({
      path: record.relativeFile.replace(/^docs\//, ''),
      sourceOfTruth: record.metadata.source_of_truth ?? 'false',
      status: record.metadata.status,
      title: record.title,
    }));
}

function renderActiveCatalog(root) {
  const rows = activeDocuments(root);

  if (rows.length === 0) {
    return renderTable(
      ['Chemin', 'Statut', 'Source de vérité', 'Titre'],
      [['-', '-', '-', 'Aucun document actif trouvé.']],
    );
  }

  return renderTable(
    ['Chemin', 'Statut', 'Source de vérité', 'Titre'],
    rows.map((row) => [
      `\`${row.path}\``,
      row.status,
      row.sourceOfTruth,
      row.title,
    ]),
  );
}

function renderDocsReadme(root, today) {
  return `${preservedFrontmatter(root, 'docs/README.md', today)}# Carte de documentation

${GENERATED_NOTICE}

Ce document est l'index de référence généré de la documentation KRAAK. Il
indique les sources actives, les archives et les commandes de contrôle
documentaire.

## Sources de vérité

| Domaine | Point d'entrée | Rôle |
| --- | --- | --- |
| Onboarding | [\`README.md\`](../README.md) | Démarrage rapide du dépôt |
| Règles assistants | [\`AGENTS.md\`](../AGENTS.md) | Workflow IA, qualité et périmètre |
| Architecture racine | [\`ARCHITECTURE.md\`](../ARCHITECTURE.md) | Limites techniques transverses |
| Architecture active | [\`architecture/\`](architecture/) | Système courant |
| Décisions | [\`decisions/README.md\`](decisions/README.md) | ADR et arbitrages validés |
| Produit | [\`product/\`](product/) | Périmètre MVP et parcours |
| Engineering | [\`engineering/\`](engineering/) | Contribution, tests et développement |
| Operations | [\`operations/\`](operations/) | Environnements, release et incident |
| Planning | [\`planning/GITHUB_PROJECT.md\`](planning/GITHUB_PROJECT.md) | Pilotage GitHub Project #6 |
| Référence | [\`reference/\`](reference/) | Matériel d'appui non autoritaire |
| Généré | [\`generated/README.md\`](generated/README.md) | Artefacts produits par automatisation |
| Archive | [\`archive/README.md\`](archive/README.md) | Historique uniquement |

## Règle de précédence

\`\`\`text
ADR acceptée > architecture active > runbook/spec actif >
matériel de référence > archive historique
\`\`\`

Quand deux documents se contredisent, appliquer cette règle puis corriger le
document obsolète dans le même changement.

## Statuts documentaires

| Statut | Sens | Métadonnées |
| --- | --- | --- |
| \`active\` | Source de vérité courante | YAML obligatoire |
| \`reference\` | Support utile, non autoritaire | YAML obligatoire |
| \`historical\` | Trace conservée d'un état passé | Notice d'archive |
| \`generated\` | Produit par automatisation | Pas de YAML lourd par fichier |

## Catalogue des documents actifs

${renderActiveCatalog(root)}

## Commandes

| Commande | Usage |
| --- | --- |
| \`pnpm docs:index:check\` | Vérifier que les index générés sont à jour |
| \`pnpm docs:index:write\` | Régénérer les index documentaires |
| \`pnpm docs:toc:check\` | Vérifier que les tables des matières Markdown sont à jour |
| \`pnpm docs:toc:write\` | Ajouter ou régénérer les tables des matières Markdown |
| \`pnpm docs:audit\` | Audit local rapide de la documentation |
| \`pnpm docs:audit:full\` | Audit complet sans échec strict |
| \`pnpm docs:audit:strict\` | Audit complet bloquant sur findings |
`;
}

function parseAdrField(content, fieldName) {
  const tableRegex = new RegExp(
    String.raw`\|\s*(?:\*\*)?${fieldName}(?:\*\*)?\s*\|\s*([^|]+)\|`,
    'i',
  );
  const listRegex = new RegExp(
    String.raw`^-\s*(?:\*\*)?${fieldName}(?:\*\*)?\s*:\s*(.+)$`,
    'im',
  );
  const boldInlineRegex = new RegExp(
    String.raw`^\*\*${fieldName}\s*:\*\*\s*(.+)$`,
    'im',
  );
  const tableMatch = content.match(tableRegex);
  const listMatch = content.match(listRegex);
  const boldInlineMatch = content.match(boldInlineRegex);

  return stripMarkdown(
    (tableMatch?.[1] ?? listMatch?.[1] ?? boldInlineMatch?.[1] ?? '-').trim(),
  );
}

function adrTitle(record, id) {
  return stripMarkdown(
    record.title
      .replace(new RegExp(String.raw`^${id}\s*(?:[-–—:]\s*)?`, 'i'), '')
      .trim(),
  );
}

function adrRecords(root) {
  return walkMarkdown(root, 'docs/decisions')
    .filter((file) => /^docs\/decisions\/ARC-\d{2}-.+\.md$/i.test(file))
    .map((file) => {
      const record = readMarkdownRecord(root, file);
      const idMatch = /^(ARC-\d{2})-/i.exec(path.basename(file));

      if (!idMatch) {
        throw new Error(`ADR sans identifiant ARC valide: ${file}`);
      }

      const id = idMatch[1].toUpperCase();

      return {
        date: parseAdrField(record.content, 'Date'),
        file: record.relativeFile.replace('docs/decisions/', ''),
        id,
        number: Number(id.slice(4)),
        status: parseAdrField(record.content, 'Statut'),
        title: adrTitle(record, id),
      };
    })
    .sort(
      (left, right) =>
        left.number - right.number || left.file.localeCompare(right.file, 'fr'),
    );
}

function renderDecisionsReadme(root, today) {
  const rows = adrRecords(root);

  const indexRows =
    rows.length === 0
      ? [['-', '-', '-', '-']]
      : rows.map((row) => [
          `\`${row.id}\``,
          `[${row.title}](${row.file})`,
          row.status,
          row.date,
        ]);

  return `${preservedFrontmatter(root, 'docs/decisions/README.md', today)}# Architecture Decision Records (ADR)

${GENERATED_NOTICE}

Ce répertoire centralise les décisions d'architecture formelles du projet
KRAAK. L'index ci-dessous est dérivé des fichiers \`ARC-XX-*.md\`.

## Convention

- Chaque ADR suit le format : \`ARC-XX-titre-court.md\`
- Langue : français pour le contenu, anglais pour les identifiants techniques
- Statuts possibles : \`Proposée\`, \`Acceptée\`, \`Remplacée\`, \`Abandonnée\`,
  \`Appliquée\`

## Index

${renderTable(['ID', 'Titre', 'Statut', 'Date'], indexRows)}
`;
}

function archiveSummary(content) {
  const heading = findArchiveSummaryHeading(content);

  if (!heading) {
    return '-';
  }

  const summaryStart = heading.index + heading.text.length;
  const remainingContent = content.slice(summaryStart);
  const sectionEnd = findFirstExistingIndex(remainingContent, [
    '\n## ',
    '\n---',
  ]);
  const summaryContent = remainingContent.slice(
    0,
    sectionEnd ?? remainingContent.length,
  );

  return renderArchiveSummaryText(summaryContent);
}

function findArchiveSummaryHeading(content) {
  const archiveSummaryHeadings = [
    '## Pourquoi ces documents sont archives',
    '## Pourquoi ces documents sont archivés',
    '## Pourquoi ces documents sont archivées',
  ];

  for (const text of archiveSummaryHeadings) {
    const index = content.indexOf(text);

    if (index !== -1) {
      return { index, text };
    }
  }

  return undefined;
}

function findFirstExistingIndex(content, markers) {
  const indexes = markers
    .map((marker) => content.indexOf(marker))
    .filter((index) => index !== -1);

  return indexes.length > 0 ? Math.min(...indexes) : undefined;
}

function renderArchiveSummaryText(summaryContent) {
  return (
    stripMarkdown(summaryContent.replaceAll(/\s+/g, ' ')).replace(/\.$/, '.') ||
    '-'
  );
}

function archiveRecords(root) {
  const archiveRoot = path.join(root, 'docs', 'archive');

  if (!existsSync(archiveRoot)) {
    return [];
  }

  return readdirSync(archiveRoot, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => {
      const readme = path.join(archiveRoot, entry.name, 'README.md');

      if (!existsSync(readme)) {
        return {
          archivedOn: '-',
          directory: `${entry.name}/`,
          status: '-',
          summary: 'README.md manquant.',
          title: entry.name,
        };
      }

      const relativeReadme = normalizePath(path.relative(root, readme));
      const record = readMarkdownRecord(root, relativeReadme);

      return {
        archivedOn: record.metadata.archived_on ?? '-',
        directory: `${entry.name}/`,
        status: record.metadata.status ?? '-',
        summary: archiveSummary(record.content),
        title: record.title,
      };
    })
    .sort((left, right) => left.directory.localeCompare(right.directory, 'fr'));
}

function renderArchiveReadme(root, today) {
  const rows = archiveRecords(root);
  const archiveRows =
    rows.length === 0
      ? [['-', '-', '-', '-', '-']]
      : rows.map((row) => [
          `\`${row.directory}\``,
          row.status,
          row.archivedOn,
          row.title,
          row.summary,
        ]);

  return `${preservedFrontmatter(root, 'docs/archive/README.md', today)}# Archive documentaire

${GENERATED_NOTICE}

Ce dossier conserve les documents historiques. Ils peuvent expliquer une
décision, une migration ou un état antérieur, mais ils ne définissent pas le
processus courant.

## Règle d'utilisation

- Chercher d'abord dans [\`../README.md\`](../README.md).
- Ne pas citer un document archivé comme source active.
- Si une information historique reste utile, l'extraire vers un document actif
  ou de référence, puis laisser l'archive intacte.
- Ne pas ajouter de métadonnées lourdes aux preuves brutes et snapshots.
- Chaque sous-dossier d'archive garde un \`README.md\` avec la raison
  d'archivage, la date d'archivage, les documents actifs de remplacement et la
  règle de suppression ultérieure.

## Sous-dossiers

${renderTable(
  ['Dossier', 'Statut', "Date d'archivage", 'Titre', 'Contenu'],
  archiveRows,
)}
`;
}

function buildRawDocsIndexes(rootDirectory = process.cwd(), options = {}) {
  const root = path.resolve(rootDirectory);
  const today = options.today ?? todayIsoDate();

  return new Map([
    ['docs/README.md', renderDocsReadme(root, today)],
    ['docs/decisions/README.md', renderDecisionsReadme(root, today)],
    ['docs/archive/README.md', renderArchiveReadme(root, today)],
  ]);
}

export async function buildDocsIndexes(
  rootDirectory = process.cwd(),
  options = {},
) {
  const rawIndexes = buildRawDocsIndexes(rootDirectory, options);
  const formattedIndexes = new Map();

  for (const [relativeFile, content] of rawIndexes) {
    formattedIndexes.set(
      relativeFile,
      await prettier.format(renderMarkdownWithToc(content), {
        parser: 'markdown',
      }),
    );
  }

  return formattedIndexes;
}

function writeIndexes(root, indexes) {
  for (const [relativeFile, content] of indexes) {
    const target = path.join(root, relativeFile);

    mkdirSync(path.dirname(target), { recursive: true });
    writeFileSync(target, content, 'utf8');
    console.log(`Wrote ${relativeFile}`);
  }
}

function checkIndexes(root, indexes) {
  const outdated = [];

  for (const [relativeFile, expected] of indexes) {
    const target = path.join(root, relativeFile);
    const actual =
      existsSync(target) && statSync(target).isFile() ? readText(target) : '';

    if (actual !== expected) {
      outdated.push(relativeFile);
    }
  }

  return outdated;
}

function usage() {
  return `Usage:
  node scripts/generate-docs-index.mjs --check
  node scripts/generate-docs-index.mjs --write

Options:
  --check   fail when generated documentation indexes are stale
  --write   update generated documentation indexes
`;
}

function parseArgs(args) {
  const check = args.includes('--check');
  const write = args.includes('--write');
  const help = args.includes('--help') || args.includes('-h');
  const unknown = args.filter(
    (arg) => !['--check', '--write', '--help', '-h'].includes(arg),
  );

  if (help) {
    return { mode: 'help' };
  }

  if (unknown.length > 0) {
    return { error: `Unknown option: ${unknown.join(', ')}` };
  }

  if (check === write) {
    return { error: 'Choose exactly one mode: --check or --write.' };
  }

  return { mode: check ? 'check' : 'write' };
}

export async function runCli(
  args = process.argv.slice(2),
  root = process.cwd(),
) {
  const parsed = parseArgs(args);

  if (parsed.mode === 'help') {
    console.log(usage());
    return 0;
  }

  if (parsed.error) {
    console.error(parsed.error);
    console.error(usage());
    return 2;
  }

  const indexes = await buildDocsIndexes(root);

  if (parsed.mode === 'write') {
    writeIndexes(root, indexes);
    return 0;
  }

  const outdated = checkIndexes(root, indexes);

  if (outdated.length === 0) {
    console.log('Documentation indexes are up to date.');
    return 0;
  }

  for (const file of outdated) {
    console.error(`${file} is not up to date.`);
  }

  console.error(
    'Run `pnpm docs:index:write` to regenerate documentation indexes.',
  );
  return 1;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = await runCli();
}
